cd $R && tar xzf d.tgz < /dev/null && sha256sum f41d* 0d28* < /dev/null | cut -c1-12
nice -n 10 /scratch/jjyeung/envs/p1cpu/bin/python -I - <<'PY'
import sqlite3,json,glob,collections
A=json.load(open(glob.glob('f41d*')[0])); Bd=json.load(open(glob.glob('0d28*')[0]))
ah,at=set(A['heldout_scenes']),set(A['train_scenes']); bh,bt=set(Bd['heldout_scenes']),set(Bd['train_scenes'])
c=sqlite3.connect('file:/scratch/jjyeung/n30_mirror/rows_r1/out/a2_vqa_v7/vqa/rows.sqlite?mode=ro',uri=True)
cnt=collections.Counter(); ex=collections.defaultdict(list); scenes=set()
for i,row in c.execute('select i,row from rows'):
    r=json.loads(row); s=f"{r.get('dataset')}/{r.get('scene')}"; scenes.add(s)
    part='base' if i<195471 else 'extra'
    k=(part, 'in0d28train' if s in bt else ('in0d28held' if s in bh else ('inF41Dheld' if s in ah else ('inF41Dtrain_only' if s in at else 'outside_both'))))
    cnt[k]+=1
    if len(ex[k])<3: ex[k].append((i,s,r.get('qid')))
for k,v in sorted(cnt.items()): print(k,v,ex[k])
print('distinct scenes',len(scenes),'in 0d28 train',len(scenes&bt),'in f41d held',len(scenes&ah))
PY
